/// Returns the table of sprites for a sheet.
pub fn table(sheet: Sheet) -> &'static [SpriteRect] {
    match sheet {
        Sheet::Main => MAIN,
        Sheet::Titlebar => TITLEBAR,
        Sheet::Cbuttons => CBUTTONS,
        Sheet::Numbers => NUMBERS,
        Sheet::NumsEx => NUMS_EX,
        Sheet::Playpaus => PLAYPAUS,
        Sheet::Monoster => MONOSTER,
        Sheet::Posbar => POSBAR,
        Sheet::Volume => VOLUME,
        Sheet::Balance => BALANCE,
        Sheet::Shufrep => SHUFREP,
        Sheet::Text => TEXT,
        Sheet::Pledit => PLEDIT,
        Sheet::Eqmain => EQMAIN,
        Sheet::EqEx => EQ_EX,
        Sheet::Gen => GEN,
        Sheet::Genex => GENEX,
        Sheet::Video => VIDEO,
        Sheet::Mb => MB,
    }
}

/// Looks up a sprite by its Webamp name within a sheet.
pub fn lookup(sheet: Sheet, name: &str) -> Option<SpriteRect> {
    table(sheet).iter().copied().find(|r| r.name == name)
}

/// Resolves a character to its TEXT.BMP cell `(row, col)`.
///
/// Fallbacks mirror Webamp: the exact character first, then its lowercase form
/// (the font stores letters in lowercase keys), then its uppercase form, and
/// finally the space cell for anything the font does not contain.
pub fn font_cell(c: char) -> (u32, u32) {
    let find = |ch: char| {
        FONT_LOOKUP
            .iter()
            .find(|(k, _)| *k == ch)
            .map(|(_, cell)| *cell)
    };
    let mut lower = c.to_lowercase();
    let lower = match (lower.next(), lower.next()) {
        (Some(l), None) => Some(l),
        _ => None,
    };
    let mut upper = c.to_uppercase();
    let upper = match (upper.next(), upper.next()) {
        (Some(u), None) => Some(u),
        _ => None,
    };
    find(c)
        .or_else(|| lower.and_then(find))
        .or_else(|| upper.and_then(find))
        .unwrap_or((0, 30))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lookup_returns_exact_webamp_rects() {
        assert_eq!(
            lookup(Sheet::Cbuttons, "MAIN_PLAY_BUTTON"),
            Some(SpriteRect {
                name: "MAIN_PLAY_BUTTON",
                x: 23,
                y: 0,
                w: 23,
                h: 18
            })
        );
        assert_eq!(
            lookup(Sheet::Volume, "MAIN_VOLUME_BACKGROUND"),
            Some(SpriteRect {
                name: "MAIN_VOLUME_BACKGROUND",
                x: 0,
                y: 0,
                w: 68,
                h: 420
            })
        );
        assert_eq!(lookup(Sheet::Cbuttons, "NO_SUCH_SPRITE"), None);
        assert_eq!(lookup(Sheet::Main, "MAIN_PLAY_BUTTON"), None);
    }

    #[test]
    fn font_cells_follow_webamp_fallbacks() {
        assert_eq!(font_cell('a'), (0, 0));
        assert_eq!(
            font_cell('A'),
            (0, 0),
            "uppercase falls back to the lowercase key"
        );
        assert_eq!(font_cell('Z'), (0, 25));
        assert_eq!(font_cell('7'), (1, 7));
        assert_eq!(font_cell(' '), (0, 30));
        assert_eq!(font_cell('\u{2026}'), (1, 10));
        assert_eq!(
            font_cell('\u{20ac}'),
            (0, 30),
            "unknown characters become a space"
        );
    }

    #[test]
    fn font_table_covers_every_text_sprite() {
        for (ch, (row, col)) in FONT_LOOKUP {
            let name = format!("CHARACTER_{}", *ch as u32);
            let r = lookup(Sheet::Text, &name).unwrap_or_else(|| panic!("missing {name}"));
            assert_eq!((r.x, r.y, r.w, r.h), (col * 5, row * 6, 5, 6));
        }
    }
}
